// Streamed-event projection (x-speakeasy-cli-commands output.stream.select):
// the declared intent writes the selected string field of each server-sent
// event raw to stdout as the event arrives. These tests prove the delivery is
// incremental — each event lands in its own Write, observed before the server
// is allowed to send the next one — rather than batched at the end of the
// stream, and that the bytes are exact.

// intentStreamWireTokens is the selected pointer below the SSE data envelope;
// the mock server nests each chunk under it.
var intentStreamWireTokens = []string{"content"}

const intentStreamSentinel = "[DONE]"

// intentStreamGap is the deliberate pause between events on the server.
const intentStreamGap = 300 * time.Millisecond

// intentStreamMinGap is the arrival gap the client must observe between
// consecutive projected writes: comfortably below the server pause (so
// scheduling jitter cannot fail the test) but far above anything a
// batch-at-end implementation could produce (all writes within microseconds).
const intentStreamMinGap = 200 * time.Millisecond

// intentStreamHandshakeTimeout bounds how long the server waits for the
// client to observe the previous event before it gives up. Generous on
// purpose: on a loaded machine the CLI may take seconds to reach its first
// write, whereas a batch-at-end implementation never satisfies the handshake
// no matter how long the server waits (its writes only happen once the
// stream has ended, which the server is holding open).
const intentStreamHandshakeTimeout = 30 * time.Second

// intentStreamTestTimeout bounds one in-process CLI run.
const intentStreamTestTimeout = 90 * time.Second

type timedWrite struct {
	at   time.Time
	data []byte
}

// recordingWriter timestamps every Write it receives (the CLI's stdout) and
// signals each one so the mock server can wait for the client to observe
// event N before it sends event N+1.
type recordingWriter struct {
	mu       sync.Mutex
	writes   []timedWrite
	observed chan struct{}
}

func newRecordingWriter() *recordingWriter {
	return &recordingWriter{observed: make(chan struct{}, 64)}
}

func (w *recordingWriter) Write(p []byte) (int, error) {
	w.mu.Lock()
	w.writes = append(w.writes, timedWrite{at: time.Now(), data: append([]byte(nil), p...)})
	w.mu.Unlock()
	select {
	case w.observed <- struct{}{}:
	default:
	}
	return len(p), nil
}

func (w *recordingWriter) snapshot() []timedWrite {
	w.mu.Lock()
	defer w.mu.Unlock()
	return append([]timedWrite(nil), w.writes...)
}

func (w *recordingWriter) String() string {
	var b bytes.Buffer
	for _, tw := range w.snapshot() {
		b.Write(tw.data)
	}
	return b.String()
}

// intentStreamPayload nests value under the selected pointer (below the SSE
// data envelope).
func intentStreamPayload(value interface{}) string {
	for i := len(intentStreamWireTokens) - 1; i >= 0; i-- {
		value = map[string]interface{}{intentStreamWireTokens[i]: value}
	}
	data, _ := json.Marshal(value)
	return string(data)
}

// intentStreamServer is a mock SSE endpoint. Between events it waits (with a
// deadline) until the client reports having written the previous event, then
// pauses intentStreamGap, so an implementation that held output back until
// the stream ended would deadlock the handshake instead of merely being slow.
type intentStreamServer struct {
	*httptest.Server
	handshakeTimedOut atomic.Bool
	sent              []time.Time
	mu                sync.Mutex
	receivedBodies    [][]byte
}

func newIntentStreamServer(t *testing.T, chunks []string, waitFor <-chan struct{}) *intentStreamServer {
	t.Helper()
	s := &intentStreamServer{}
	s.Server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		require.NoError(t, err)
		s.mu.Lock()
		s.receivedBodies = append(s.receivedBodies, body)
		s.mu.Unlock()
		flusher, ok := w.(http.Flusher)
		require.True(t, ok, "httptest ResponseWriter must support Flush")
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.WriteHeader(http.StatusOK)
		flusher.Flush()

		for i, chunk := range chunks {
			if i > 0 && waitFor != nil {
				select {
				case <-waitFor:
				case <-time.After(intentStreamHandshakeTimeout):
					s.handshakeTimedOut.Store(true)
					return
				}
				time.Sleep(intentStreamGap)
			}
			s.mu.Lock()
			s.sent = append(s.sent, time.Now())
			s.mu.Unlock()
			fmt.Fprintf(w, "data: %s\n\n", intentStreamPayload(chunk))
			flusher.Flush()
		}
		// An event without the selected field is skipped by the projection.
		fmt.Fprint(w, "data: {}\n\n")
		flusher.Flush()
		if intentStreamSentinel != "" {
			fmt.Fprintf(w, "data: %s\n\n", intentStreamSentinel)
			flusher.Flush()
		}
	}))
	t.Cleanup(s.Close)
	return s
}

func (s *intentStreamServer) lastBody(t *testing.T) map[string]interface{} {
	t.Helper()
	s.mu.Lock()
	defer s.mu.Unlock()
	require.NotEmpty(t, s.receivedBodies)
	var body map[string]interface{}
	require.NoError(t, json.Unmarshal(s.receivedBodies[len(s.receivedBodies)-1], &body))
	return body
}

// runIntentStream executes the declared streaming intent in-process with
// stdout bound to out. It deliberately does not go through RunWithServer,
// which injects an explicit --output-format json (an explicit format is one
// of the ways a user opts out of the projection).
func runIntentStream(t *testing.T, ctx context.Context, out io.Writer, serverURL string, extra ...string) (string, error) {
	t.Helper()
	return runIntentStreamWithRootFlags(t, ctx, out, serverURL, nil, extra...)
}

// runIntentStreamWithRootFlags places rootFlags ahead of the command path.
func runIntentStreamWithRootFlags(t *testing.T, ctx context.Context, out io.Writer, serverURL string, rootFlags []string, extra ...string) (string, error) {
	t.Helper()
	h := NewCLITestHarness(t)
	h.resetAndSetupEnv()

	rootCmd, err := cli.NewRootCommand()
	require.NoError(t, err)
	rootCmd.SetOut(out)
	rootCmd.SetErr(h.stderr)

	args := append(baseArgs(), rootFlags...)
	args = append(args, "--server-url", serverURL, "--color", "never")
	args = append(args, "say")
	args = append(args, "hello")
	args = append(args, extra...)
	err = cli.ExecuteRoot(ctx, rootCmd, args)
	return h.GetStderr(), err
}

type intentStreamPrompter struct {
	answers map[string][]string
	fields  []interactive.PromptField
}

func (p *intentStreamPrompter) Prompt(_ *cobra.Command, fields []interactive.PromptField) ([]interactive.PromptAnswer, error) {
	p.fields = append([]interactive.PromptField(nil), fields...)
	answers := make([]interactive.PromptAnswer, len(fields))
	for i, field := range fields {
		if values, ok := p.answers[field.ID]; ok {
			answers[i] = interactive.PromptAnswer{Set: true, Values: values}
		}
	}
	return answers, nil
}

// runPromptedIntentStream mirrors runIntentStream without a positional and
// without the harness's explicit JSON format. beforeCommand models root flags
// supplied by the user before selecting the command.
func runPromptedIntentStream(t *testing.T, out io.Writer, serverURL string, p interactive.Prompter, beforeCommand ...string) (string, error) {
	t.Helper()
	h := NewCLITestHarness(t)
	h.resetAndSetupEnv()
	rootCmd, err := cli.NewRootCommand()
	require.NoError(t, err)
	rootCmd.SetOut(out)
	rootCmd.SetErr(h.stderr)
	// Prompting is opt-in at runtime (--interactive; interactiveByDefault may be false).
	args := append([]string{"--interactive"}, beforeCommand...)
	args = append(args, "--server-url", serverURL, "--color", "never")
	args = append(args, "say")
	ctx, cancel := context.WithTimeout(context.Background(), intentStreamTestTimeout)
	defer cancel()
	ctx = interactive.WithPrompter(ctx, p)
	err = cli.ExecuteRoot(ctx, rootCmd, args)
	return h.GetStderr(), err
}

// TestIntentStream_IncrementalDelivery is the timing proof: three chunks,
// 300ms apart on the server, must arrive as three separate writes with
// >=200ms between them, byte-exact, with one trailing newline appended
// because the content did not end with one.
func TestIntentStream_IncrementalDelivery(t *testing.T) {
	chunks := []string{"Hello, ", "streaming ", "wörld — 🌍 done"}
	rec := newRecordingWriter()
	srv := newIntentStreamServer(t, chunks, rec.observed)

	ctx, cancel := context.WithTimeout(context.Background(), intentStreamTestTimeout)
	defer cancel()
	start := time.Now()
	stderr, err := runIntentStream(t, ctx, rec, srv.URL)
	require.NoError(t, err, "stderr: %s", stderr)
	require.False(t, srv.handshakeTimedOut.Load(), "the server never observed the client's write for an event: output was not incremental (stdout so far: %q)", rec.String())

	writes := rec.snapshot()
	require.GreaterOrEqual(t, len(writes), len(chunks), "expected one write per event, got %d writes: %q", len(writes), rec.String())

	// One Write per event, byte-exact, no framing or quoting.
	for i, chunk := range chunks {
		assert.Equal(t, chunk, string(writes[i].data), "write %d must be exactly event %d's text", i, i)
	}
	// Exactly the concatenation plus one terminating newline.
	assert.Equal(t, strings.Join(chunks, "")+"\n", rec.String())
	assert.Empty(t, stderr)

	// Timing: consecutive event writes are separated by the server pause.
	for i := 1; i < len(chunks); i++ {
		gap := writes[i].at.Sub(writes[i-1].at)
		assert.GreaterOrEqual(t, gap, intentStreamMinGap, "gap between write %d and %d was %s; events were batched", i-1, i, gap)
	}
	assert.GreaterOrEqual(t, time.Since(start), time.Duration(len(chunks)-1)*intentStreamMinGap)

	// Causality: every event write happened before the server sent the next event.
	srv.mu.Lock()
	sent := append([]time.Time(nil), srv.sent...)
	srv.mu.Unlock()
	require.Len(t, sent, len(chunks))
	for i := 1; i < len(chunks); i++ {
		assert.True(t, writes[i-1].at.Before(sent[i]), "write %d (%s) must precede the server sending event %d (%s)", i-1, writes[i-1].at, i, sent[i])
	}

	t.Logf("timing: %d writes; per-write arrival offsets from start:", len(writes))
	for i, w := range writes {
		t.Logf("  write %d at +%s: %q", i, w.at.Sub(start).Round(time.Millisecond), string(w.data))
	}
}

