func TestIntentStream_DryRunJSONPrintsPreview(t *testing.T) {
	srv := newIntentStreamServer(t, nil, nil)
	var out bytes.Buffer
	ctx, cancel := context.WithTimeout(context.Background(), intentStreamTestTimeout)
	defer cancel()
	stderr, err := runIntentStream(t, ctx, &out, srv.URL, "--dry-run", "--output-format", "json")
	require.NoError(t, err, "stderr: %s", stderr)
	// An explicit JSON dry-run selects the machine preview protocol: one
	// {"dry_run":true,"request":{...}} object on stdout, never a stream.
	var preview struct {
		DryRun  bool `json:"dry_run"`
		Request struct {
			Method string `json:"method"`
		} `json:"request"`
	}
	require.NoError(t, json.Unmarshal([]byte(strings.TrimSpace(out.String())), &preview), "stdout: %s", out.String())
	assert.True(t, preview.DryRun)
	assert.Equal(t, "POST", preview.Request.Method)
}
func TestIntentStream_PromptedIncrementalDeliveryPreservesPreset(t *testing.T) {
	chunks := []string{"Prompted ", "streaming ", "works"}
	rec := newRecordingWriter()
	srv := newIntentStreamServer(t, chunks, rec.observed)
	p := &intentStreamPrompter{answers: map[string][]string{
		"arg:" + "prompt": {"hello from the prompt"},
	}}

	stderr, err := runPromptedIntentStream(t, rec, srv.URL, p)
	require.NoError(t, err, "stderr: %s", stderr)
	require.False(t, srv.handshakeTimedOut.Load())
	assert.Equal(t, strings.Join(chunks, "")+"\n", rec.String(), "projection must preserve the single trailing-LF rule")
	assert.Equal(t, true, srv.lastBody(t)["stream"], "the intent preset must survive interactive argument injection")

	writes := rec.snapshot()
	require.GreaterOrEqual(t, len(writes), len(chunks))
	srv.mu.Lock()
	sent := append([]time.Time(nil), srv.sent...)
	srv.mu.Unlock()
	for i := 1; i < len(chunks); i++ {
		assert.GreaterOrEqual(t, writes[i].at.Sub(writes[i-1].at), intentStreamMinGap)
		assert.True(t, writes[i-1].at.Before(sent[i]), "prompted output must be observed before the next event is sent")
	}
}

func TestIntentStream_PromptedExplicitJSONKeepsNDJSON(t *testing.T) {
	chunks := []string{"a", "b"}
	srv := newIntentStreamServer(t, chunks, nil)
	p := &intentStreamPrompter{answers: map[string][]string{
		"arg:" + "prompt": {"hello"},
	}}
	var out bytes.Buffer
	stderr, err := runPromptedIntentStream(t, &out, srv.URL, p, "--output-format", "json")
	require.NoError(t, err, "stderr: %s", stderr)
	lines := strings.Split(strings.TrimSpace(out.String()), "\n")
	require.Len(t, lines, len(chunks)+1)
	for _, line := range lines {
		var event map[string]interface{}
		require.NoError(t, json.Unmarshal([]byte(line), &event), "NDJSON line: %s", line)
	}
}

func TestIntentStream_BodyFileResolvesBeforeDeclaredFlagAndPresetMerge(t *testing.T) {
	bodyPath := filepath.Join(t.TempDir(), "request.json")
	require.NoError(t, os.WriteFile(bodyPath, []byte(`{}`), 0o600))
	srv := newIntentStreamServer(t, nil, nil)
	var out bytes.Buffer
	ctx, cancel := context.WithTimeout(context.Background(), intentStreamTestTimeout)
	defer cancel()
	stderr, err := runIntentStream(t, ctx, &out, srv.URL, "--request", "@"+bodyPath, "--stream=true")
	require.NoError(t, err, "stderr: %s", stderr)
	body := srv.lastBody(t)
	assert.Equal(t, "hello", body["prompt"])
	assert.Equal(t, true, body["stream"], "the declared flag and preset must merge after resolving the body file")
}

