// gets none appended (the payload is never altered, only terminated).
func TestIntentStream_NoDoubleNewline(t *testing.T) {
	chunks := []string{"line one\n", "line two\n"}
	rec := newRecordingWriter()
	srv := newIntentStreamServer(t, chunks, rec.observed)

	ctx, cancel := context.WithTimeout(context.Background(), intentStreamTestTimeout)
	defer cancel()
	stderr, err := runIntentStream(t, ctx, rec, srv.URL)
	require.NoError(t, err, "stderr: %s", stderr)
	assert.Equal(t, "line one\nline two\n", rec.String())
}

// TestIntentStream_ExplicitJSONKeepsNDJSON: an explicit --output-format json
// opts out of the projection and keeps one full event per line.
func TestIntentStream_ExplicitJSONKeepsNDJSON(t *testing.T) {
	chunks := []string{"a", "b", "c"}
	srv := newIntentStreamServer(t, chunks, nil)

	var out bytes.Buffer
	ctx, cancel := context.WithTimeout(context.Background(), intentStreamTestTimeout)
	defer cancel()
	stderr, err := runIntentStream(t, ctx, &out, srv.URL, "--output-format", "json")
	require.NoError(t, err, "stderr: %s", stderr)

	var lines []map[string]interface{}
	for _, line := range strings.Split(strings.TrimSpace(out.String()), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		var obj map[string]interface{}
		require.NoError(t, json.Unmarshal([]byte(line), &obj), "NDJSON line: %s", line)
		lines = append(lines, obj)
	}
	require.Len(t, lines, len(chunks)+1, "one JSON event per line, including the event without the selected field")
	var got []string
	for _, obj := range lines[:len(chunks)] {
		var value interface{} = obj["data"]
		for _, token := range intentStreamWireTokens {
			m, ok := value.(map[string]interface{})
			require.True(t, ok)
			value = m[token]
		}
		got = append(got, value.(string))
	}
	assert.Equal(t, chunks, got)
}

